<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f3f7fb;
        --panel: rgba(255, 255, 255, 0.92);
        --text: #0f172a;
        --muted: #64748b;
        --border: #d7e0ea;
        --accent: #2563eb;
        --accent-hover: #1d4ed8;
        --error: #b91c1c;
        --shadow: 0 20px 60px rgba(15, 23, 42, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, #dbeafe 0, transparent 35%),
          radial-gradient(circle at bottom right, #e0e7ff 0, transparent 32%),
          var(--bg);
        display: grid;
        place-items: center;
        padding: 24px;
      }

      .card {
        width: min(100%, 680px);
        background: var(--panel);
        backdrop-filter: blur(10px);
        border: 1px solid rgba(255, 255, 255, 0.75);
        border-radius: 24px;
        box-shadow: var(--shadow);
        padding: 32px;
      }

      .eyebrow {
        margin: 0 0 10px;
        font-size: 0.9rem;
        font-weight: 600;
        letter-spacing: 0.04em;
        text-transform: uppercase;
        color: var(--accent);
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 4vw, 2.8rem);
        line-height: 1.1;
      }

      .subtitle {
        margin: 12px 0 0;
        max-width: 58ch;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        margin-top: 28px;
        display: grid;
        gap: 18px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 600;
      }

      input {
        width: 100%;
        border: 1px solid var(--border);
        border-radius: 14px;
        padding: 14px 16px;
        font: inherit;
        background: #fff;
        color: var(--text);
        transition: border-color 0.15s ease, box-shadow 0.15s ease;
      }

      input:focus {
        outline: none;
        border-color: rgba(37, 99, 235, 0.65);
        box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.14);
      }

      .hint {
        margin: 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .error {
        margin: 0;
        color: var(--error);
        font-size: 0.95rem;
        min-height: 1.2em;
      }

      .error[hidden] {
        display: none;
      }

      .field-invalid input {
        border-color: rgba(185, 28, 28, 0.7);
      }

      button {
        border: 0;
        border-radius: 14px;
        padding: 14px 18px;
        font: inherit;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--accent), #4f46e5);
        cursor: pointer;
        transition: transform 0.15s ease, filter 0.15s ease;
      }

      button:hover {
        filter: brightness(1.03);
        transform: translateY(-1px);
      }

      button:focus {
        outline: none;
        box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.2);
      }

      @media (max-width: 640px) {
        .card {
          padding: 24px;
          border-radius: 20px;
        }
      }
    </style>
  </head>
  <body>
    <main class="card">
      <p class="eyebrow">Support</p>
      <h1>Contact our team</h1>
      <p class="subtitle">
        Send us a message and we&apos;ll get back to you as soon as possible.
      </p>

      <form id="contact-form" novalidate>
        <div class="form-field" data-field="full-name">
          <label for="full-name">Full name</label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            required
          />
          <p class="error" id="full-name-error" hidden></p>
        </div>

        <div class="form-field" data-field="email-address">
          <label for="email-address">Email address</label>
          <input
            id="email-address"
            name="emailAddress"
            type="email"
            autocomplete="email"
            required
          />
          <p class="error" id="email-address-error" hidden></p>
        </div>

        <div class="form-field" data-field="phone-number">
          <label for="phone-number">Phone number</label>
          <input
            id="phone-number"
            name="phoneNumber"
            type="tel"
            autocomplete="tel"
            inputmode="tel"
            aria-describedby="phone-number-hint phone-number-error"
            placeholder="+1 555 123 4567"
          />
          <p class="hint" id="phone-number-hint">Include country code if applicable, for example +1 555 123 4567.</p>
          <p class="error" id="phone-number-error" hidden></p>
        </div>

        <button type="submit">Send message</button>
      </form>
    </main>

    <script>
      const form = document.getElementById('contact-form');
      const fields = [
        {
          input: document.getElementById('full-name'),
          error: document.getElementById('full-name-error'),
          field: document.querySelector('[data-field="full-name"]'),
          message: 'Please enter your full name.',
          required: true,
        },
        {
          input: document.getElementById('email-address'),
          error: document.getElementById('email-address-error'),
          field: document.querySelector('[data-field="email-address"]'),
          message: 'Please enter a valid email address.',
          required: true,
        },
        {
          input: document.getElementById('phone-number'),
          error: document.getElementById('phone-number-error'),
          field: document.querySelector('[data-field="phone-number"]'),
          message: 'Use a valid phone number format, such as +1 555 123 4567.',
          required: false,
        },
      ];

      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const phonePattern = /^[+()\-.\s\d]{7,}$/;
      let submittedOnce = false;

      function setError(field, message) {
        field.field.classList.toggle('field-invalid', Boolean(message));
        field.error.textContent = message;
        field.error.hidden = !message;
        field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
      }

      function validateField(field) {
        const value = field.input.value.trim();

        if (field.required && !value) {
          setError(field, field.message);
          return false;
        }

        if (field.input.type === 'email' && value && !emailPattern.test(value)) {
          setError(field, field.message);
          return false;
        }

        if (field.input.type === 'tel' && value && !phonePattern.test(value)) {
          setError(field, field.message);
          return false;
        }

        setError(field, '');
        return true;
      }

      form.addEventListener('submit', (event) => {
        event.preventDefault();
        submittedOnce = true;

        const isValid = fields.map(validateField).every(Boolean);

        if (isValid) {
          form.reset();
          fields.forEach(setError => setError);
          fields.forEach((field) => setError(field, ''));
        }
      });

      fields.forEach((field) => {
        field.input.addEventListener('input', () => {
          if (submittedOnce) {
            validateField(field);
          }
        });

        field.input.addEventListener('blur', () => {
          if (submittedOnce) {
            validateField(field);
          }
        });
      });
    </script>
  </body>
</html>
